import math
import numpy as np

def strategy(hist, state, pos, ind) -> dict:
    close = hist.close[-1]
    atr = ind.atr(hist, 14)[-1]

    # Initialize state keys
    if "entry_price" not in state:
        state["entry_price"] = 0.0
    if "entry_atr" not in state:
        state["entry_atr"] = 0.0
    if "trade_direction" not in state:
        state["trade_direction"] = 0.0  # 0=flat, 1=long, -1=short
    if "entry_bar" not in state:
        state["entry_bar"] = 0.0
    if "breakeven_triggered" not in state:
        state["breakeven_triggered"] = False
    if "hwm" not in state:
        state["hwm"] = 0.0  # high water mark for longs, low water mark for shorts
    if "box_anchor" not in state:
        state["box_anchor"] = 0.0
    if "box_shifts" not in state:
        state["box_shifts"] = 0.0
    if "cooldown_bars" not in state:
        state["cooldown_bars"] = 0.0
    if "breakout_level" not in state:
        state["breakout_level"] = 0.0
    if "breakout_bar" not in state:
        state["breakout_bar"] = 0.0
    if "breakout_direction" not in state:
        state["breakout_direction"] = 0.0
    if "last_entry_day" not in state:
        state["last_entry_day"] = -1.0

    current_bar = len(hist) - 1
    current_time = hist.time[-1]
    current_day = current_time // (24 * 3600 * 1000)

    # Donchian breakout signal (96-bar)
    donchian_n = 96
    if current_bar >= donchian_n:
        prior_high = ind.highest(hist.high[:-1], donchian_n)[-1]
        prior_low = ind.lowest(hist.low[:-1], donchian_n)[-1]
        bullish_signal = close > prior_high
        bearish_signal = close < prior_low
    else:
        bullish_signal = False
        bearish_signal = False

    # HTF trend filter (240-minute, 20-period EMA)
    htf_hist = hist.htf(240)
    if len(htf_hist.close) > 0:
        htf_ema = ind.ema(htf_hist.close, 20)
        htf_close = htf_hist.close[-1]
        htf_ema_val = htf_ema[-1]
        long_allowed = htf_close > htf_ema_val
        short_allowed = htf_close < htf_ema_val
    else:
        long_allowed = True
        short_allowed = True

    # Cooldown logic
    if state["cooldown_bars"] > 0:
        state["cooldown_bars"] -= 1

    # Daily cap logic
    can_enter_today = (current_day != state["last_entry_day"])

    # Determine entry signal
    entry_signal = 0  # 0=none, 1=long, -1=short

    if pos == 0.0:  # Only enter when flat
        if state["cooldown_bars"] <= 0 and can_enter_today:
            if bullish_signal and long_allowed:
                entry_signal = 1
                state["last_entry_day"] = current_day
            elif bearish_signal and short_allowed:
                entry_signal = -1
                state["last_entry_day"] = current_day
    else:
        # Opposite signal closes the trade
        if state["trade_direction"] == 1.0 and bearish_signal:
            entry_signal = 0  # Close long
        elif state["trade_direction"] == -1.0 and bullish_signal:
            entry_signal = 0  # Close short

    # Position sizing (atr_risk: r=0.01, k=3.0)
    target_size = 0.01 * close / (3.0 * atr)
    target_size = max(0.05, min(1.0, target_size))
    target_size = round(target_size * 20) / 20  # Round to 0.05 grid

    # Handle entry
    if entry_signal != 0 and pos == 0.0:
        state["entry_price"] = close
        state["entry_atr"] = atr
        state["entry_bar"] = current_bar
        state["trade_direction"] = float(entry_signal)
        state["breakeven_triggered"] = False
        state["box_anchor"] = close
        state["box_shifts"] = 0.0
        if entry_signal == 1.0:
            state["hwm"] = close
            target = target_size
        else:
            state["hwm"] = close
            target = -target_size
    elif entry_signal == 0 and pos != 0.0:
        # Close position
        target = 0.0
        state["trade_direction"] = 0.0
        state["cooldown_bars"] = 4.0
    else:
        target = pos

    # Update HWM while in trade
    if pos != 0.0:
        if state["trade_direction"] == 1.0:
            state["hwm"] = max(state["hwm"], hist.high[-1])
        else:
            state["hwm"] = min(state["hwm"], hist.low[-1])

    # Box shift logic (lo=2.0, hi=2.0, step=2.0)
    if pos != 0.0:
        profit_distance = abs(close - state["entry_price"])
        step_size = 2.0 * state["entry_atr"]
        steps_cleared = int(profit_distance / step_size)

        if state["trade_direction"] == 1.0:
            if close > state["entry_price"]:
                new_shifts = min(steps_cleared, int((profit_distance - state["box_shifts"] * step_size) / step_size))
                if new_shifts > 0:
                    state["box_anchor"] += new_shifts * step_size
                    state["box_shifts"] += new_shifts
        else:
            if close < state["entry_price"]:
                new_shifts = min(steps_cleared, int((profit_distance - state["box_shifts"] * step_size) / step_size))
                if new_shifts > 0:
                    state["box_anchor"] -= new_shifts * step_size
                    state["box_shifts"] += new_shifts

    # Calculate stop and take levels
    stop_level = None
    take_level = None

    if pos != 0.0:
        entry_atr = state["entry_atr"]

        # Box shift stop and take
        box_stop = state["box_anchor"] - 2.0 * entry_atr
        box_take = state["box_anchor"] + 2.0 * entry_atr

        # Breakeven logic (a=0.5)
        if not state["breakeven_triggered"]:
            if state["trade_direction"] == 1.0:
                if close >= state["entry_price"] + 0.5 * entry_atr:
                    state["breakeven_triggered"] = True
            else:
                if close <= state["entry_price"] - 0.5 * entry_atr:
                    state["breakeven_triggered"] = True

        # Trailing HWM (b=1.5, after_be=True)
        if state["breakeven_triggered"]:
            if state["trade_direction"] == 1.0:
                trailing_stop = state["hwm"] - 1.5 * entry_atr
                stop_level = max(box_stop, trailing_stop)
            else:
                trailing_stop = state["hwm"] + 1.5 * entry_atr
                stop_level = min(box_stop, trailing_stop)
        else:
            stop_level = box_stop

        take_level = box_take

    return {
        "target": target,
        "stop": stop_level,
        "take": take_level
    }

