def strategy(hist, state, pos, ind) -> dict:
    close = hist.close[-1]
    atr_val = ind.atr(hist, 14)[-1]
    rsi_val = ind.rsi(hist.close, 7)

    # Initialize state keys if needed
    if "entry_price" not in state:
        state["entry_price"] = 0.0
    if "entry_atr" not in state:
        state["entry_atr"] = 0.0
    if "signal_bar" not in state:
        state["signal_bar"] = -1
    if "add_count" not in state:
        state["add_count"] = 0
    if "last_add_price" not in state:
        state["last_add_price"] = 0.0
    if "hwm" not in state:
        state["hwm"] = 0.0
    if "cooldown_until" not in state:
        state["cooldown_until"] = -1

    current_bar = len(hist) - 1

    # Cooldown check
    if current_bar < state["cooldown_until"]:
        return {"target": pos, "stop": None, "take": None}

    # Detect RSI signal (cross events)
    signal = None
    if len(rsi_val) >= 2:
        prev_rsi = rsi_val[-2]
        curr_rsi = rsi_val[-1]

        # Bullish: RSI crosses above 20 (was at or below, now strictly above)
        if prev_rsi <= 20 and curr_rsi > 20:
            signal = "long"
        # Bearish: RSI crosses below 80 (was at or above, now strictly below)
        elif prev_rsi >= 80 and curr_rsi < 80:
            signal = "short"

    target = pos
    stop_price = None
    take_price = None

    # Handle opposite signal when in position
    if pos != 0.0:
        if signal == "long" and pos < 0:
            # Short position, long signal -> exit
            target = 0.0
            state["cooldown_until"] = current_bar + 4
        elif signal == "short" and pos > 0:
            # Long position, short signal -> exit
            target = 0.0
            state["cooldown_until"] = current_bar + 4
        else:
            # In position, no opposite signal; apply risk management
            bars_since_signal = current_bar - state["signal_bar"]

            # Time stop: exit at bar 32
            if bars_since_signal >= 32:
                target = 0.0
                state["cooldown_until"] = current_bar + 4
            else:
                # Fixed stop: 3 ATR away
                entry_atr = state["entry_atr"]
                if pos > 0:
                    stop_price = state["entry_price"] - 3.0 * entry_atr
                else:
                    stop_price = state["entry_price"] + 3.0 * entry_atr

                # Pyramid logic: add when price moves 2 ATR in favor from last add
                if state["add_count"] < 2:
                    if pos > 0 and close >= state["last_add_price"] + 2.0 * entry_atr:
                        # Add long
                        new_pos = min(pos + 0.25, 1.0)
                        target = new_pos
                        state["add_count"] += 1
                        state["last_add_price"] = close
                    elif pos < 0 and close <= state["last_add_price"] - 2.0 * entry_atr:
                        # Add short
                        new_pos = max(pos - 0.25, -1.0)
                        target = new_pos
                        state["add_count"] += 1
                        state["last_add_price"] = close
    else:
        # Flat, check for entry signal
        if signal == "long":
            target = 0.25
            state["entry_price"] = close
            state["entry_atr"] = atr_val
            state["signal_bar"] = current_bar
            state["add_count"] = 0
            state["last_add_price"] = close
        elif signal == "short":
            target = -0.25
            state["entry_price"] = close
            state["entry_atr"] = atr_val
            state["signal_bar"] = current_bar
            state["add_count"] = 0
            state["last_add_price"] = close

    # Apply stop/take on active positions
    if target != 0.0:
        entry_atr = state["entry_atr"]
        if target > 0:
            stop_price = state["entry_price"] - 3.0 * entry_atr
        else:
            stop_price = state["entry_price"] + 3.0 * entry_atr

    # Round target to 0.05 grid
    target = round(target * 20) / 20

    return {"target": target, "stop": stop_price, "take": take_price}

