    high = hist.high[-1]
    low = hist.low[-1]
    atr_val = ind.atr(hist, 14)[-1]

    # Initialize state keys
    if "armed" not in state:
        state["armed"] = False
    if "breakout_level" not in state:
        state["breakout_level"] = 0.0
    if "breakout_bar" not in state:
        state["breakout_bar"] = -1
    if "entry_price" not in state:
        state["entry_price"] = 0.0
    if "entry_atr" not in state:
        state["entry_atr"] = 0.0
    if "entry_bar" not in state:
        state["entry_bar"] = -1
    if "bearish_armed" not in state:
        state["bearish_armed"] = False
    if "bearish_level" not in state:
        state["bearish_level"] = 0.0
    if "bearish_bar" not in state:
        state["bearish_bar"] = -1

    current_bar = len(hist) - 1

    # Check for bearish signal: close below 48-bar low, then high touches it within 8 bars
    if pos > 0:
        low_48 = ind.lowest(hist.low, 48)[-1]
        bars_since_bearish = current_bar - state["bearish_bar"]

        # Detect new bearish breakout
        if current_bar >= 48:
            prev_close = hist.close[-2] if len(hist) > 1 else close
            if prev_close >= low_48 and close < low_48:
                state["bearish_armed"] = True
                state["bearish_level"] = low_48
                state["bearish_bar"] = current_bar

        # Check if bearish signal triggers (high touches level within 8 bars)
        if state["bearish_armed"] and bars_since_bearish <= 8:
            if high >= state["bearish_level"]:
                return {"target": 0.0, "stop": None, "take": None}
        elif state["bearish_armed"] and bars_since_bearish > 8:
            state["bearish_armed"] = False

    # Breakout pullback logic for long entries
    if pos == 0:
        high_48 = ind.highest(hist.high, 48)[-1]
        low_48 = ind.lowest(hist.low, 48)[-1]

        # Detect new bullish breakout (close above 48-bar high)
        if current_bar >= 48:
            prev_close = hist.close[-2] if len(hist) > 1 else close
            if prev_close <= high_48 and close > high_48:
                state["armed"] = True
                state["breakout_level"] = high_48
                state["breakout_bar"] = current_bar

        # Check for new bearish breakout that resets (close below 48-bar low)
        if current_bar >= 48:
            prev_close = hist.close[-2] if len(hist) > 1 else close
            if prev_close >= low_48 and close < low_48:
                state["armed"] = False
                state["bearish_armed"] = True
                state["bearish_level"] = low_48
                state["bearish_bar"] = current_bar

        # Check if armed setup is still valid (within 8 bars of breakout)
        bars_since_breakout = current_bar - state["breakout_bar"]
        if state["armed"] and bars_since_breakout > 8:
            state["armed"] = False

        # Check for bullish signal: low touches breakout level while armed
        if state["armed"] and bars_since_breakout <= 8:
            if low <= state["breakout_level"]:
                state["entry_price"] = close
                state["entry_atr"] = atr_val
                state["entry_bar"] = current_bar
                state["armed"] = False
                target = 0.5

                # Calculate stop: 1 x entry ATR below entry price
                stop_price = state["entry_price"] - state["entry_atr"]

                # Calculate take-profit: none specified, use None
                take_price = None

                return {"target": target, "stop": stop_price, "take": take_price}

    # Time stop: exit if 32 bars have passed since entry
    if pos > 0:
        bars_since_entry = current_bar - state["entry_bar"]
        if bars_since_entry >= 32:
            return {"target": 0.0, "stop": None, "take": None}

    # Maintain stop while in position
    if pos > 0:
        stop_price = state["entry_price"] - state["entry_atr"]
        return {"target": pos, "stop": stop_price, "take": None}

    return {"target": pos, "stop": None, "take": None}

