    # Get SMAs
    sma_fast = ind.sma(hist.close, 20)
    sma_slow = ind.sma(hist.close, 200)

    # Get 4h HTF data for filter
    htf_4h = hist.htf(240)
    htf_close_4h = htf_4h.close
    ema_4h = ind.ema(htf_close_4h, 50)

    target = pos
    stop_price = None
    take_price = None

    # Determine signal: SMA cross
    prev_fast = sma_fast[-2]
    prev_slow = sma_slow[-2]
    curr_fast = sma_fast[-1]
    curr_slow = sma_slow[-1]

    bullish_cross = (prev_fast <= prev_slow) and (curr_fast > curr_slow)
    bearish_cross = (prev_fast >= prev_slow) and (curr_fast < curr_slow)

    # Check HTF filter (4h EMA)
    filter_long_ok = htf_close_4h[-1] > ema_4h[-1]
    filter_short_ok = htf_close_4h[-1] < ema_4h[-1]

    # Entry logic
    if pos == 0.0:
        if bullish_cross and filter_long_ok:
            target = 0.75
            state["entry_price"] = close
            state["entry_atr"] = atr_val
            state["trade_dir"] = 1.0
            state["hwm"] = close
            state["lwm"] = close
            state["be_triggered"] = False
            state["partial_taken"] = False
        elif bearish_cross and filter_short_ok:
            target = -0.75
            state["entry_price"] = close
            state["entry_atr"] = atr_val
            state["trade_dir"] = -1.0
            state["hwm"] = close
            state["lwm"] = close
            state["be_triggered"] = False
            state["partial_taken"] = False
    else:
        # In a position: check for opposite cross to flip
        if state["trade_dir"] == 1.0 and bearish_cross:
            target = 0.0
            state["trade_dir"] = 0.0
        elif state["trade_dir"] == -1.0 and bullish_cross:
            target = 0.0
            state["trade_dir"] = 0.0
        else:
            # Update HWM/LWM for trailing stop
            if state["trade_dir"] == 1.0:
                state["hwm"] = max(state["hwm"], hist.high[-1])
            elif state["trade_dir"] == -1.0:
                state["lwm"] = min(state["lwm"], hist.low[-1])

            # Check breakeven condition
            if not state["be_triggered"]:
                if state["trade_dir"] == 1.0:
                    if close >= state["entry_price"] + 1.5 * state["entry_atr"]:
                        state["be_triggered"] = True
                elif state["trade_dir"] == -1.0:
                    if close <= state["entry_price"] - 1.5 * state["entry_atr"]:
                        state["be_triggered"] = True

    # Calculate stop and take prices
    if pos != 0.0:
        if state["trade_dir"] == 1.0:
            # Long position
            if state["be_triggered"]:
                stop_price = state["entry_price"]
            else:
                stop_price = state["hwm"] - 1.5 * state["entry_atr"]
            take_price = state["entry_price"] + 4.0 * state["entry_atr"]
        elif state["trade_dir"] == -1.0:
            # Short position
            if state["be_triggered"]:
                stop_price = state["entry_price"]
            else:
                stop_price = state["lwm"] + 1.5 * state["entry_atr"]
            take_price = state["entry_price"] - 4.0 * state["entry_atr"]

    return {
        "target": target,
        "stop": stop_price,
        "take": take_price
    }

