    w = 6.0

    box_high = ind.highest(hist.high[:-1], m)[-1]
    box_low = ind.lowest(hist.low[:-1], m)[-1]
    box_height = box_high - box_low

    is_valid_box = box_height <= w * atr_val

    bullish_signal = False
    bearish_signal = False

    if is_valid_box:
        if close > box_high:
            bullish_signal = True
        if close < box_low:
            bearish_signal = True

    # HTF trend filter (60-minute, 50-period EMA)
    htf_60 = hist.htf(60)
    if len(htf_60.close) > 0:
        ema_50 = ind.ema(htf_60.close, 50)
        htf_close = htf_60.close[-1]
        htf_ema = ema_50[-1]

        filter_allows_long = htf_close > htf_ema
        filter_allows_short = htf_close < htf_ema
    else:
        filter_allows_long = True
        filter_allows_short = True

    # Cooldown check
    in_cooldown = current_bar < state["cooldown_until"]

    # Time stop check
    time_stop_triggered = False
    if state["signal_bar"] >= 0 and pos != 0.0:
        bars_since_signal = current_bar - state["signal_bar"]
        if bars_since_signal >= 32:
            time_stop_triggered = True

    # Determine target
    target = pos
    stop = None
    take = None

    if time_stop_triggered:
        target = 0.0
    elif pos == 0.0 and not in_cooldown:
        # Check for entry signal
