        # Calculate stops and takes
        entry_atr = state["entry_atr"]
        entry_price = state["entry_price"]

        # Fixed stop: 1.5 ATR away
        fixed_stop_level = entry_price - 1.5 * entry_atr

        # Breakeven: once 1.5 ATR in profit, move stop to entry
        if close >= entry_price + 1.5 * entry_atr:
            state["be_triggered"] = True

        if state["be_triggered"]:
            fixed_stop_level = entry_price

        # Trailing stop: 3 ATR behind best price (only after breakeven triggered)
        if state["be_triggered"]:
            trailing_stop_level = state["best_price"] - 3.0 * entry_atr
            stop = max(fixed_stop_level, trailing_stop_level)
        else:
            stop = fixed_stop_level

        return {"target": pos, "stop": stop, "take": take}

    # We're flat; check for entry signals

    # Cooldown check
    if state["cooldown_bars"] > 0:
