    state["entry_atr"] = atr
    state["best_price"] = close
    state["be_triggered"] = False
    state["box_top"] = box_high
    state["box_bottom"] = box_low

    # Calculate initial stop and take
    stop = close - 1.5 * atr

    target = position_fraction

    return {"target": target, "stop": stop, "take": take}

