    if "signal_direction" not in state:
        state["signal_direction"] = 0

    current_bar = len(hist) - 1

    # Detect RSI crossover signals
    signal = 0
    if not math.isnan(rsi_val) and not math.isnan(rsi_prev):
        # Bullish: RSI crosses above 25
        if rsi_prev <= 25 and rsi_val > 25:
            signal = 1
        # Bearish: RSI crosses below 75
        elif rsi_prev >= 75 and rsi_val < 75:
            signal = -1

    # Opposite signal flattens position
    if pos != 0 and signal != 0 and signal != state["signal_direction"]:
        return {"target": 0.0, "stop": None, "take": None}

    # Entry logic: only when flat
    target = pos
    stop_price = None
    take_price = None

