        state["entry_price"] = close
        state["entry_atr"] = atr_val
        state["signal_bar"] = current_bar
        state["adds_count"] = 0
        state["last_add_price"] = close
        state["box_anchor"] = close
        state["hwm"] = close if signal == 1 else close
        state["signal_direction"] = signal

        # Sizing: pyramid with f0=0.25
        target = 0.25 * signal

    elif pos != 0:
        # Pyramid logic: add 0.25 when price moves 2 entry ATRs in favor
        if state["adds_count"] < 2:
            threshold = 2.0 * state["entry_atr"]
            if state["signal_direction"] == 1:
                if close >= state["last_add_price"] + threshold:
                    state["adds_count"] += 1
                    state["last_add_price"] = close
                    target = min(0.25 * (1 + state["adds_count"]), 1.0)
            elif state["signal_direction"] == -1:
                if close <= state["last_add_price"] - threshold:
                    state["adds_count"] += 1
                    state["last_add_price"] = close
                    target = max(-0.25 * (1 + state["adds_count"]), -1.0)

        # Box shift logic: move box forward by 1 entry ATR per 1 entry ATR close in profit
        step_size = state["entry_atr"]
        if state["signal_direction"] == 1:
            profit = close - state["entry_price"]
            steps = int(profit / step_size)
            if steps > 0:
                new_anchor = state["entry_price"] + steps * step_size
                state["box_anchor"] = new_anchor
        elif state["signal_direction"] == -1:
            profit = state["entry_price"] - close
            steps = int(profit / step_size)
            if steps > 0:
                new_anchor = state["entry_price"] - steps * step_size
                state["box_anchor"] = new_anchor

        # Update high water mark for trailing stop
        if state["signal_direction"] == 1:
            state["hwm"] = max(state["hwm"], hist.high[-1])
        elif state["signal_direction"] == -1:
            state["hwm"] = min(state["hwm"], hist.low[-1])

        # Box shift stop and take
        box_stop_dist = 2.0 * state["entry_atr"]
        box_take_dist = 2.0 * state["entry_atr"]

        if state["signal_direction"] == 1:
            box_stop = state["box_anchor"] - box_stop_dist
            box_take = state["box_anchor"] + box_take_dist
        else:
            box_stop = state["box_anchor"] + box_stop_dist
            box_take = state["box_anchor"] - box_take_dist

        # Trailing stop: 4 entry ATRs behind the extreme
        trailing_dist = 4.0 * state["entry_atr"]
        if state["signal_direction"] == 1:
            trailing_stop = state["hwm"] - trailing_dist
        else:
            trailing_stop = state["hwm"] + trailing_dist

        # Use tightest stop
        if state["signal_direction"] == 1:
            stop_price = max(box_stop, trailing_stop)
        else:
            stop_price = min(box_stop, trailing_stop)

        take_price = box_take

    # Round target to 0.05 grid
    target = round(target * 20) / 20

    return {"target": target, "stop": stop_price, "take": take_price}

