    htf_close = hist.htf(240).close
    htf_ema = ind.ema(htf_close, 50)
    can_long = htf_close[-1] > htf_ema[-1]
    can_short = htf_close[-1] < htf_ema[-1]

    # Donchian breakout signal detection (48-bar lookback)
    if current_bar >= 48:
        prior_high = ind.highest(hist.high[:-1], 48)[-1]
        prior_low = ind.lowest(hist.low[:-1], 48)[-1]

        # Bullish breakout: close strictly above 48-bar high
        if close > prior_high:
            if state["armed_direction"] != 1:
                state["breakout_level"] = prior_high
                state["breakout_bar"] = current_bar
                state["armed_direction"] = 1.0

        # Bearish breakout: close strictly below 48-bar low
        if close < prior_low:
            if state["armed_direction"] != -1:
                state["breakout_level"] = prior_low
                state["breakout_bar"] = current_bar
                state["armed_direction"] = -1.0

    # Retest signal logic (wait = 32 bars)
    signal_long = False
    signal_short = False

    if state["armed_direction"] == 1.0:
        bars_since_breakout = current_bar - state["breakout_bar"]
        if bars_since_breakout <= 32:
            # Bullish retest: low touches or goes below breakout level
            if hist.low[-1] <= state["breakout_level"]:
