    if state["cooldown_bars"] > 0:
        state["cooldown_bars"] -= 1

    # SMA cross signal
    sma_fast = ind.sma(hist.close, 20)
    sma_slow = ind.sma(hist.close, 200)

    bullish_cross = False
    bearish_cross = False

    if len(sma_fast) > 1 and len(sma_slow) > 1:
        if not np.isnan(sma_fast[-2]) and not np.isnan(sma_slow[-2]):
            if not np.isnan(sma_fast[-1]) and not np.isnan(sma_slow[-1]):
                # Bullish cross: fast was at or below slow, now strictly above
                if sma_fast[-2] <= sma_slow[-2] and sma_fast[-1] > sma_slow[-1]:
                    bullish_cross = True
                # Bearish cross: fast was at or above slow, now strictly below
                if sma_fast[-2] >= sma_slow[-2] and sma_fast[-1] < sma_slow[-1]:
                    bearish_cross = True

    target = pos
    stop = None
    take = None

    # If we're flat and get a bullish signal, enter long
    if pos == 0.0 and bullish_cross and state["cooldown_bars"] == 0:
        state["entry_price"] = close
        state["entry_atr"] = atr_val
        state["signal_bar"] = current_bar
        state["last_add_price"] = close
        state["add_count"] = 0
        state["best_price"] = close
        state["breakeven_triggered"] = False
        target = 0.25

    # If we're in a long and get a bearish cross, close
    elif pos > 0.0 and bearish_cross:
        state["last_trade_close_bar"] = current_bar
        state["cooldown_bars"] = 4
        target = 0.0

    # Pyramid logic: add when price moves 1x entry ATR in our favor from last add
    elif pos > 0.0 and state["add_count"] < 2:
        profit_from_last_add = close - state["last_add_price"]
        if profit_from_last_add >= state["entry_atr"]:
            new_pos = pos + 0.25
            if new_pos > 1.0:
                new_pos = 1.0
            if new_pos > pos:
                target = new_pos
                state["last_add_price"] = close
                state["add_count"] += 1

    # Update best price for trailing stop (highest high for longs)
    if pos > 0.0:
        if close > state["best_price"]:
            state["best_price"] = close

    # Calculate stop and take levels
    if pos > 0.0:
        # Fixed stop: 1x entry ATR below entry
        fixed_stop_level = state["entry_price"] - state["entry_atr"]

        # Breakeven: once 2x entry ATR in profit, move stop to entry
        profit = close - state["entry_price"]
        if profit >= 2.0 * state["entry_atr"]:
            state["breakeven_triggered"] = True

        if state["breakeven_triggered"]:
            stop = state["entry_price"]
        else:
            stop = fixed_stop_level

        # Take profit: 6x entry ATR above entry
        take = state["entry_price"] + 6.0 * state["entry_atr"]

    return {"target": target, "stop": stop, "take": take}

