    if "breakout_dir" not in state:
        state["breakout_dir"] = 0.0  # 1=bullish, -1=bearish
    if "armed" not in state:
        state["armed"] = False
    if "last_trade_close_bar" not in state:
        state["last_trade_close_bar"] = -999.0
    if "last_entry_day" not in state:
        state["last_entry_day"] = -1.0

    current_bar = len(hist) - 1
    current_time_ms = hist.time[-1]
    current_day = current_time_ms // (24 * 3600 * 1000)

    # Donchian levels for breakout_pullback signal
    donchian_high = ind.highest(hist.high[:-1], 48)[-1] if len(hist) > 48 else hist.high[-1]
    donchian_low = ind.lowest(hist.low[:-1], 48)[-1] if len(hist) > 48 else hist.low[-1]

    target = pos
    stop_level = None
    take_level = None

    # Check for new breakout (level condition, true on every bar it holds)
    bullish_breakout = close > donchian_high if len(hist) > 48 else False
    bearish_breakout = close < donchian_low if len(hist) > 48 else False

    # Update armed breakout/retest setup
    if bullish_breakout:
        state["breakout_level"] = donchian_high
        state["breakout_bar"] = float(current_bar)
        state["breakout_dir"] = 1.0
        state["armed"] = True
    elif bearish_breakout:
        state["breakout_level"] = donchian_low
        state["breakout_bar"] = float(current_bar)
        state["breakout_dir"] = -1.0
        state["armed"] = True

    # Check if armed setup has expired
    if state["armed"]:
        bars_since_breakout = current_bar - int(state["breakout_bar"])
        if bars_since_breakout > 8:
            state["armed"] = False

    # Check for retest signal (trigger while armed)
    signal_dir = 0.0
    if state["armed"]:
        if state["breakout_dir"] == 1.0:
            # Bullish: low touches or goes below breakout level
            if low <= state["breakout_level"]:
                signal_dir = 1.0
                state["armed"] = False
        elif state["breakout_dir"] == -1.0:
            # Bearish: high touches or goes above breakout level
            if high >= state["breakout_level"]:
                signal_dir = -1.0
                state["armed"] = False

    # Daily cap check
    can_enter = True
    if signal_dir != 0.0:
        if int(state["last_entry_day"]) == int(current_day):
            can_enter = False
        else:
            state["last_entry_day"] = float(current_day)

