            state["box_stop"] = close - 1.0 * atr_val
            state["box_take"] = close + 3.0 * atr_val
        else:
            state["box_anchor"] = close
            state["box_stop"] = close + 1.0 * atr_val
            state["box_take"] = close - 3.0 * atr_val

        # Size: 0.25 of equity
        target = 0.25 * signal_dir

    # Opposite signal while in trade: flip position
    elif signal_dir != 0.0 and signal_dir != state["trade_dir"] and pos != 0.0:
        target = 0.0
        state["trade_dir"] = 0.0
        state["last_trade_close_bar"] = float(current_bar)

    # Pyramid logic (while in trade)
    if pos != 0.0 and state["trade_dir"] != 0.0:
        profit_from_last_add = (close - state["last_add_price"]) * state["trade_dir"]

        if profit_from_last_add >= 2.0 * state["entry_atr"] and state["pyramid_adds"] < 2.0:
            state["pyramid_adds"] += 1.0
            state["last_add_price"] = close
            add_size = 0.25
            target = pos + add_size * state["trade_dir"]

        # Box shift logic
        profit_from_anchor = (close - state["box_anchor"]) * state["trade_dir"]
        if profit_from_anchor >= 2.0 * state["entry_atr"]:
            shift_steps = int(profit_from_anchor / (2.0 * state["entry_atr"]))
            for _ in range(shift_steps):
                if state["trade_dir"] == 1.0:
                    state["box_anchor"] += 2.0 * state["entry_atr"]
                    state["box_stop"] += 2.0 * state["entry_atr"]
                    state["box_take"] += 2.0 * state["entry_atr"]
                else:
                    state["box_anchor"] -= 2.0 * state["entry_atr"]
                    state["box_stop"] -= 2.0 * state["entry_atr"]
                    state["box_take"] -= 2.0 * state["entry_atr"]

    # Set stop and take levels
    if pos != 0.0:
        stop_level = state["box_stop"]
        take_level = state["box_take"]

    # Exit on stop/take (handled by engine, but we track closure)
    if pos != 0.0:
        if state["trade_dir"] == 1.0:
            if low <= stop_level or high >= take_level:
                state["trade_dir"] = 0.0
                state["last_trade_close_bar"] = float(current_bar)
        elif state["trade_dir"] == -1.0:
            if high >= stop_level or low <= take_level:
                state["trade_dir"] = 0.0
                state["last_trade_close_bar"] = float(current_bar)

    # Round target to 0.05 grid
    target = round(target * 20) / 20

    return {"target": target, "stop": stop_level, "take": take_level}

