    donchian_high = ind.highest(hist.high, 97)[-2]  # 96 bars before current
    donchian_low = ind.lowest(hist.low, 97)[-2]

    long_breakout = close > donchian_high
    short_breakout = close < donchian_low

    # Arm breakout_pullback setup
    if long_breakout and state["breakout_direction"] != 1:
        state["breakout_level"] = donchian_high
        state["breakout_direction"] = 1
        state["breakout_bar"] = current_bar
    elif short_breakout and state["breakout_direction"] != -1:
        state["breakout_level"] = donchian_low
        state["breakout_direction"] = -1
        state["breakout_bar"] = current_bar

