    else:
        filter_long_ok = True
        filter_short_ok = True

    # Daily cap check
    daily_cap_ok = state["entries_today"] < 2

    # Determine entry signal
    entry_signal = 0  # 0=none, 1=long, -1=short

    if pos == 0.0 and not in_cooldown and daily_cap_ok:
