    if entry_signal != 0:
        target_size = 0.01 * close / (2.0 * atr)
        target_size = max(0.05, min(1.0, target_size))
        target_size = round(target_size / 0.05) * 0.05

        if entry_signal == 1:
            target = target_size
        else:
            target = -target_size

        state["entry_price"] = close
        state["entry_atr"] = atr
        state["box_anchor"] = close
        state["box_anchor_bar"] = current_bar
        state["partial_taken"] = False
        state["hwm"] = close
        state["entries_today"] += 1
    elif pos == 0.0 and entry_signal == 0:
        target = 0.0
    else:
        target = pos

    # Close position on opposite signal
    if pos != 0.0 and entry_signal == 0 and (signal_long or signal_short):
        if (signal_long and pos < 0) or (signal_short and pos > 0):
            target = 0.0
            state["cooldown_until"] = current_bar + 48

    # Calculate stop and take levels (box_shift: lo=2.0, hi=2.0, step=2.0)
    stop = None
    take = None

    if pos != 0.0:
        # Update HWM for trailing
        if pos > 0:
            state["hwm"] = max(state["hwm"], hist.high[-1])
        else:
            state["hwm"] = min(state["hwm"], hist.low[-1])

        # Box shift logic
        if pos > 0:
            profit = close - state["entry_price"]
            steps_cleared = int(profit / (2.0 * state["entry_atr"]))
            if steps_cleared > 0:
                new_anchor = state["entry_price"] + steps_cleared * 2.0 * state["entry_atr"]
                if new_anchor > state["box_anchor"]:
                    state["box_anchor"] = new_anchor

            stop = state["box_anchor"] - 2.0 * state["entry_atr"]
            take = state["box_anchor"] + 2.0 * state["entry_atr"]
        else:
            profit = state["entry_price"] - close
            steps_cleared = int(profit / (2.0 * state["entry_atr"]))
            if steps_cleared > 0:
                new_anchor = state["entry_price"] - steps_cleared * 2.0 * state["entry_atr"]
                if new_anchor < state["box_anchor"]:
                    state["box_anchor"] = new_anchor

            stop = state["box_anchor"] + 2.0 * state["entry_atr"]
            take = state["box_anchor"] - 2.0 * state["entry_atr"]

    target = round(target / 0.05) * 0.05

    return {"target": target, "stop": stop, "take": take}

