        if rsi_prev <= 25 and rsi_curr > 25:
            bullish_signal = True
        # Bearish: RSI crosses below 75 (was at or above, now strictly below)
        if rsi_prev >= 75 and rsi_curr < 75:
            bearish_signal = True

    target = pos
    stop = None
    take = None

    # If flat, check for entry signals
