            target = 0.0
        elif pos < 0 and bullish_signal:
            target = 0.0
        else:
            # Pyramid logic: add when price moves 1 entry ATR in favor from last add price
            if state["add_count"] < 2:  # max 2 adds
                if pos > 0:
