                    state["last_add_price"] = close
                    state["add_count"] += 1
            elif pos < 0 and close <= state["last_add_price"] - 2.0 * entry_atr:
                add_size = 0.5
                if abs(pos) + add_size <= 1.0:
                    target = pos - add_size
                    state["last_add_price"] = close
                    state["add_count"] += 1

        # Breakeven stop: once up 1 ATR, move stop to entry price
        if not state["breakeven_triggered"]:
            if pos > 0 and close >= entry_price + 1.0 * entry_atr:
                state["breakeven_triggered"] = True
            elif pos < 0 and close <= entry_price - 1.0 * entry_atr:
                state["breakeven_triggered"] = True

