        if state["breakeven_triggered"]:
            stop_price = entry_price
        else:
            if pos > 0:
                stop_price = entry_price - 1.0 * entry_atr
            else:
                stop_price = entry_price + 1.0 * entry_atr

        # Trailing stop component (if breakeven not triggered, use tighter of fixed or trailing)
        trailing_stop = None
        if pos > 0:
            trailing_stop = state["best_price"] - 1.5 * entry_atr
        else:
            trailing_stop = state["best_price"] + 1.5 * entry_atr

        if trailing_stop is not None:
