                stop_price = min(stop_price, trailing_stop)

        # Take-profit at 4 ATRs
        if pos > 0:
            take_price = entry_price + 4.0 * entry_atr
        else:
            take_price = entry_price - 4.0 * entry_atr

    return {"target": target, "stop": stop_price, "take": take_price}

