    # Check cooldown: after trade ends, no entry for 16 bars
    in_cooldown = False
    if state["cooldown_bar"] >= 0:
        bars_since_cooldown_start = current_bar - state["cooldown_bar"]
        if bars_since_cooldown_start < 16:
            in_cooldown = True

