    if len(hist) > 48:
        prior_48_high = ind.highest(hist.high[:-1], 48)[-1]
    else:
        prior_48_high = hist.high[0] if len(hist) > 0 else 0.0

    if close > prior_48_high:
        state["breakout_level"] = prior_48_high
        state["breakout_bar"] = current_bar

    # Check if armed setup is still valid (within 64 bars of breakout)
    armed = False
    if state["breakout_bar"] >= 0:
        bars_since_breakout = current_bar - state["breakout_bar"]
        if bars_since_breakout <= 64:
            armed = True
        else:
            # Setup expired
            state["breakout_level"] = 0.0
            state["breakout_bar"] = -999

    # Generate signal: retest (low at or below breakout level) while armed
    signal = None
    if armed and pos == 0.0 and not in_cooldown:
        if hist.low[-1] <= state["breakout_level"]:
            signal = "long"

    # Handle position management
    target = pos
    stop = None
    take = None

    if pos == 0.0:
