        profit_atr = profit / state["entry_atr"] if state["entry_atr"] > 0 else 0

        # Breakeven stop: once 1 ATR in profit, move stop to entry and lock it
        if profit_atr >= 1.0:
            state["be_triggered"] = True

        if state["be_triggered"]:
            stop = state["entry_price"]
        else:
            stop = state["entry_price"] - 1.0 * state["entry_atr"]

