        curr_ema5 = ema5[-1]
        curr_ema100 = ema100[-1]

        # Bullish cross: ema5 was at or below ema100, now strictly above
        if prev_ema5 <= prev_ema100 and curr_ema5 > curr_ema100:
            signal = 1
        # Bearish cross: ema5 was at or above ema100, now strictly below
        elif prev_ema5 >= prev_ema100 and curr_ema5 < curr_ema100:
            signal = -1

    # Handle opposite signal when in position (closes position)
    if pos != 0.0 and signal != 0 and signal != (1 if pos > 0 else -1):
        state["cooldown_bars"] = 4
        state["signal_bar"] = -1
        state["add_count"] = 0
        return {"target": 0.0, "stop": None, "take": None}

