                new_pos = pos + 0.25
                new_pos = min(new_pos, 1.0)
                return {"target": new_pos, "stop": None, "take": None}
        else:
            if close <= state["last_add_price"] - 2.0 * state["entry_atr"]:
                state["last_add_price"] = close
                state["add_count"] += 1
                new_pos = pos - 0.25
                new_pos = max(new_pos, -1.0)
                return {"target": new_pos, "stop": None, "take": None}

    # Box shift logic: move anchor and box forward by 2 ATR steps
    if pos != 0.0:
        if pos > 0:
            profit = close - state["box_anchor"]
            if profit >= 2.0 * state["entry_atr"]:
