        state["entry_atr"] = 0.0
    if "last_add_price" not in state:
        state["last_add_price"] = 0.0
    if "adds_used" not in state:
        state["adds_used"] = 0
    if "cooldown_bars" not in state:
        state["cooldown_bars"] = 0
    if "hwm" not in state:
        state["hwm"] = 0.0
    if "be_triggered" not in state:
        state["be_triggered"] = False

    # Decrement cooldown
    if state["cooldown_bars"] > 0:
        state["cooldown_bars"] -= 1

    # Check if we just became flat (from a position)
    if pos == 0.0 and state["entry_price"] != 0.0:
        state["cooldown_bars"] = 48
        state["entry_price"] = 0.0
        state["entry_atr"] = 0.0
        state["last_add_price"] = 0.0
        state["adds_used"] = 0
        state["hwm"] = 0.0
        state["be_triggered"] = False

    target = pos
    stop = None
    take = None

    # If we're in a position, manage it
    if pos > 0.0:
        entry_price = state["entry_price"]
        entry_atr = state["entry_atr"]

        # Update HWM (highest high for longs)
        if high > state["hwm"]:
            state["hwm"] = high

        # Fixed stop: 2 ATR below entry
        stop = entry_price - 2.0 * entry_atr

        # Pyramid logic: add if close is at least 1 entry_atr above last_add_price
        if state["adds_used"] < 1:
            if close >= state["last_add_price"] + 1.0 * entry_atr:
                new_pos = pos + 0.25
                if new_pos > 1.0:
                    new_pos = 1.0
                target = new_pos
                state["last_add_price"] = close
                state["adds_used"] += 1

        return {"target": target, "stop": stop, "take": take}

    # We're flat; check for entry signal
    if state["cooldown_bars"] > 0:
        return {"target": 0.0, "stop": None, "take": None}

    # Box breakout signal (long only)
    # Box is the highest high and lowest low of the 64 bars before the current bar
    if len(hist) < 65:
        return {"target": 0.0, "stop": None, "take": None}

    box_high = ind.highest(hist.high[:-1], 64)[-1]
    box_low = ind.lowest(hist.low[:-1], 64)[-1]
    box_height = box_high - box_low

    # Box is valid if height <= 4 * ATR
    if box_height > 4.0 * atr:
        return {"target": 0.0, "stop": None, "take": None}

    # Bullish signal: close strictly above box top
    if close > box_high:
        # Entry at 0.25 size
        state["entry_price"] = close
        state["entry_atr"] = atr
        state["last_add_price"] = close
        state["adds_used"] = 0
        state["hwm"] = high
        state["be_triggered"] = False

        target = 0.25
        stop = close - 2.0 * atr

        return {"target": target, "stop": stop, "take": take}

    return {"target": 0.0, "stop": None, "take": None}

