    # Initialize state keys
    if "bull_level" not in state:
        state["bull_level"] = 0.0
    if "bear_level" not in state:
        state["bear_level"] = 0.0
    if "bull_bar" not in state:
        state["bull_bar"] = -1000
    if "bear_bar" not in state:
        state["bear_bar"] = -1000
    if "entry_price" not in state:
        state["entry_price"] = 0.0
    if "entry_atr" not in state:
        state["entry_atr"] = 0.0
    if "trade_type" not in state:
        state["trade_type"] = 0  # 0=none, 1=long, -1=short
    if "be_triggered" not in state:
        state["be_triggered"] = False

    current_bar = len(hist) - 1

    # Check for new breakouts (96-bar Donchian)
    donchian_high = ind.highest(hist.high[:-1], 96)[-1]
    donchian_low = ind.lowest(hist.low[:-1], 96)[-1]

    # Bullish breakout: close strictly above 96-bar high
    if close > donchian_high:
        state["bull_level"] = donchian_high
        state["bull_bar"] = current_bar
        state["bear_level"] = 0.0
        state["bear_bar"] = -1000

    # Bearish breakout: close strictly below 96-bar low
    if close < donchian_low:
        state["bear_level"] = donchian_low
        state["bear_bar"] = current_bar
        state["bull_level"] = 0.0
        state["bull_bar"] = -1000

    # Check if armed setups are still valid (within 32 bars)
    bull_armed = state["bull_bar"] >= 0 and (current_bar - state["bull_bar"]) <= 32
    bear_armed = state["bear_bar"] >= 0 and (current_bar - state["bear_bar"]) <= 32

    # Expire setups if outside the 32-bar window
    if not bull_armed:
        state["bull_level"] = 0.0
    if not bear_armed:
        state["bear_level"] = 0.0

    target = pos
    stop = None
    take = None

    # Check for entry signals
    entry_signal = 0  # 0=none, 1=long, -1=short

    # Bullish signal: low dips to or below bull level while armed
    if bull_armed and hist.low[-1] <= state["bull_level"]:
        entry_signal = 1

    # Bearish signal: high climbs to or above bear level while armed
    if bear_armed and hist.high[-1] >= state["bear_level"]:
        entry_signal = -1

    # Handle opposite signal while in trade (exit at next open)
    if pos != 0.0:
        if entry_signal != 0 and entry_signal != state["trade_type"]:
            target = 0.0
            state["trade_type"] = 0
            state["be_triggered"] = False
            return {"target": target, "stop": stop, "take": take}

    # Enter new trade if flat and signal present
    if pos == 0.0 and entry_signal != 0:
        target = 0.5 * entry_signal
        state["entry_price"] = close
        state["entry_atr"] = atr_val
        state["trade_type"] = entry_signal
        state["be_triggered"] = False

        # Set initial stop (1 ATR away from entry)
        if entry_signal == 1:
            stop = state["entry_price"] - 1.0 * state["entry_atr"]
        else:
            stop = state["entry_price"] + 1.0 * state["entry_atr"]

    # Manage existing trade
    elif pos != 0.0:
        # Check if breakeven condition is met (close at least 1.5 ATR in profit)
        if not state["be_triggered"]:
            if state["trade_type"] == 1 and close >= state["entry_price"] + 1.5 * state["entry_atr"]:
                state["be_triggered"] = True
            elif state["trade_type"] == -1 and close <= state["entry_price"] - 1.5 * state["entry_atr"]:
                state["be_triggered"] = True

        # Set stop based on breakeven status
        if state["be_triggered"]:
            stop = state["entry_price"]
        else:
            if state["trade_type"] == 1:
                stop = state["entry_price"] - 1.0 * state["entry_atr"]
            else:
                stop = state["entry_price"] + 1.0 * state["entry_atr"]

    return {"target": target, "stop": stop, "take": take}

