def strategy(hist, state, pos, ind) -> dict:
    close = hist.close[-1]
    high = hist.high[-1]
    low = hist.low[-1]
    atr_val = ind.atr(hist, 14)[-1]

    # Initialize state keys
    if "breakout_level" not in state:
        state["breakout_level"] = 0.0
    if "breakout_bar" not in state:
        state["breakout_bar"] = -1
    if "entry_price" not in state:
        state["entry_price"] = 0.0
    if "entry_atr" not in state:
        state["entry_atr"] = 0.0
    if "last_add_price" not in state:
        state["last_add_price"] = 0.0
    if "adds_count" not in state:
        state["adds_count"] = 0
    if "cooldown_until" not in state:
        state["cooldown_until"] = -1
    if "daily_entries" not in state:
        state["daily_entries"] = 0
    if "last_entry_day" not in state:
        state["last_entry_day"] = -1

    current_bar = len(hist) - 1
    current_time_ms = hist.time[-1]
    current_day = current_time_ms // (24 * 3600 * 1000)

    # Reset daily entry counter if new day
    if current_day != state["last_entry_day"]:
        state["daily_entries"] = 0
        state["last_entry_day"] = current_day

    # Check for bearish breakdown signal (close below 96-bar low)
    prior_96_low = ind.lowest(hist.low, 96)[-2] if len(hist) > 1 else hist.low[-1]
    bearish_signal = close < prior_96_low and pos > 0

    if bearish_signal:
        return {"target": 0.0, "stop": None, "take": None}

    # Detect new bullish breakout (close strictly above 96-bar high of prior bars)
    prior_96_high = ind.highest(hist.high, 96)[-2] if len(hist) > 1 else hist.high[-1]
    new_breakout = close > prior_96_high

    if new_breakout:
        state["breakout_level"] = prior_96_high
        state["breakout_bar"] = current_bar

    # Check if breakout setup is still armed
    bars_since_breakout = current_bar - state["breakout_bar"]
    setup_armed = 0 <= bars_since_breakout <= 32

    # Entry signal: retest of breakout level while flat and setup armed
    entry_signal = False
    if pos == 0.0 and setup_armed and state["breakout_level"] > 0:
        prev_low = hist.low[-2] if len(hist) > 1 else hist.low[-1]
        # Retest: low touches or goes below the level, close is above it
        if prev_low >= state["breakout_level"] and low <= state["breakout_level"]:
            entry_signal = True

    # Check daily cap
    if entry_signal and state["daily_entries"] >= 2:
        entry_signal = False

    # Execute entry
    if entry_signal:
        state["entry_price"] = close
        state["entry_atr"] = atr_val
        state["last_add_price"] = close
        state["adds_count"] = 0
        state["daily_entries"] += 1
        state["cooldown_until"] = -1
        target = 0.25
        stop = close - 1.0 * atr_val
        take = None
        return {"target": target, "stop": stop, "take": take}

    # Pyramid logic: add when price moves 1 ATR in favor from last add
    if pos > 0 and state["adds_count"] < 2:
        profit_from_last_add = close - state["last_add_price"]
        if profit_from_last_add >= 1.0 * state["entry_atr"]:
            new_pos = min(pos + 0.25, 1.0)
            state["last_add_price"] = close
            state["adds_count"] += 1
            stop = state["entry_price"] - 1.0 * state["entry_atr"]
            take = None
            return {"target": new_pos, "stop": stop, "take": take}

    # Maintain position with stop
    if pos > 0:
        stop = state["entry_price"] - 1.0 * state["entry_atr"]
        take = None
        return {"target": pos, "stop": stop, "take": take}

    # Flat, check cooldown
    if pos == 0.0 and current_bar <= state["cooldown_until"]:
        return {"target": 0.0, "stop": None, "take": None}

    # Exit cooldown
    if pos == 0.0 and current_bar > state["cooldown_until"]:
        state["cooldown_until"] = current_bar + 4

    return {"target": pos, "stop": None, "take": None}
